const C=window.Community;C.prepare(state);
const communityBaseRoute=route,communityBaseHome=home,communityBaseMy=myPage,communityBaseShell=adminShell,communityBasePhoto=photoPage;
const inquiryLabels={new:'未対応',in_progress:'対応中',closed:'対応済み'};
let pendingPhotoAlbum=null;
function inquiryClassLabel(value){return value==null?'未登録（以前の問い合わせ）':Number(value)===0?'クラスを忘れた':'3年'+Number(value)+'組';}
function inquiryForm(){return '<section class="section" id="contact"><div class="section-head"><div><div class="eyebrow">CONTACT US</div><h2>気になること、お気軽に。</h2><p>ログイン前でも、幹事へ問い合わせできます。</p></div></div>'+notice+'<div class="panel"><form id="communityInquiry"><div class="grid-2">'+field('name','お名前','').replace('<input ','<input placeholder="例：山田 花子" ')+field('email','返信用メールアドレス','','email').replace('<input ','<input placeholder="例：hanako@example.com" ')+'</div>'+select('class','卒業時のクラス',[['','選択してください'],...Array.from({length:10},(_,i)=>[i+1,'3年'+(i+1)+'組']),[0,'クラスを忘れた']],'').replace('<select name="class">','<select name="class" class="class-select" required>').replace('<option value="" selected>','<option value="" disabled selected>')+field('subject','件名')+'<label class="field">お問い合わせ内容<textarea name="body" maxlength="10000" rows="6" required></textarea></label><p class="mini-note">架空の内容だけを入力してください。実メールは送信せず、このブラウザーの幹事画面へ保存します。</p><p class="error-text" role="alert"></p><button class="btn">見本の問い合わせを保存</button></form></div></section>';}
home=function(){return communityBaseHome()+frame(inquiryForm());};
myPage=function(){const p=current();if(!p)return communityBaseMy();const div=document.createElement('div');div.innerHTML=communityBaseMy();const link=div.querySelector('a[href^="#/gallery/"]');if(link){link.href='#/gallery';link.textContent='フォトアルバムへ ↗';link.closest('.panel').querySelector('h3').textContent='フォトアルバム';}if(p.class===0)return div.innerHTML+frame('<section class="panel"><h2>卒業時のクラスを確認中です</h2><p>幹事が確認後に修正します。心当たりがあれば問い合わせフォームからお知らせください。</p></section>');const cs=C.contacts(state,p.class);return div.innerHTML+frame('<section class="panel"><div class="eyebrow">YOUR CLASS ORGANIZERS</div><h2>3年'+p.class+'組のクラス幹事</h2><div class="roster">'+(cs.map(c=>'<div class="name-card"><small>3年'+p.class+'組 クラス幹事</small><strong>'+esc(c.person.name)+'</strong></div>').join('')||'<p>クラス幹事は決まり次第ご案内します。</p>')+'</div><p>ご連絡は<a href="#/contact">問い合わせフォーム</a>をご利用ください。</p></section>');};
adminShell=function(section,body){return communityBaseShell(section,body).replace('</nav>','<a href="#/admin/inquiries" class="'+(section==='inquiries'?'active':'')+'">お問い合わせ</a>'+(owner()?'<a href="#/admin/contacts">クラス幹事</a>':'')+'</nav>');};
function inquiryAdmin(id=0){const items=state.inquiries;const stats=['new','in_progress','closed'].map(k=>'<div class="stat"><small>'+inquiryLabels[k]+'</small><strong>'+items.filter(i=>i.status===k).length+'件</strong></div>').join('');let body='<div class="stats-grid">'+stats+'</div>';if(!id)return adminShell('inquiries',body+'<div class="panel"><h2>お問い合わせ一覧</h2>'+table(['受付','お名前・件名','返信先','状況','担当'],items.slice().reverse().map(i=>['<a href="#/admin/inquiries/'+i.id+'">Q87-'+String(i.id).padStart(5,'0')+'</a><br>'+esc(date(i.created)),esc(i.name)+'<br>'+esc(inquiryClassLabel(i.class))+'<br>'+esc(i.subject),esc(i.email),pill(inquiryLabels[i.status]),esc(state.people.find(p=>p.id===i.assignee)?.name||'未割当')]))+'</div>');const i=items.find(i=>i.id===id);if(!i)return adminShell('inquiries','<p>問い合わせがありません。</p>');body+='<a class="text-link" href="#/admin/inquiries">← 一覧へ</a><div class="panel"><h2>'+esc(i.subject)+'</h2><p>'+esc(i.name)+' さん ／ '+esc(inquiryClassLabel(i.class))+' ／ 返信先：'+esc(i.email)+'</p><pre class="message-body">'+esc(i.body)+'</pre></div><div class="panel"><h3>対応状況・担当</h3><form id="communityInquiryStatus" data-id="'+id+'">'+select('status','対応状況',Object.entries(inquiryLabels),i.status)+select('assignee','担当幹事',[[0,'未割当'],...state.people.filter(p=>['owner','organizer'].includes(p.role)).map(p=>[p.id,p.name])],i.assignee||0)+field('reason','変更理由')+'<p class="error-text"></p><button class="btn">対応状況を保存</button></form></div><div class="panel"><h3>返信履歴</h3>'+i.replies.map(r=>'<article class="history-item"><small>'+esc(date(r.created))+' ／ '+esc(r.actor)+' ／ 開発用・未送信</small><pre class="message-body">'+esc(r.body)+'</pre></article>').join('')+'<h3>返信を書く</h3><p>宛先は問い合わせに入力された <strong>'+esc(i.email)+'</strong> です。</p><form id="communityReply" data-id="'+id+'"><label class="field">回答内容<textarea name="body" required maxlength="10000" rows="6"></textarea></label><p class="mini-note">開発用メールへ保存します。実際のメールは送信しません。</p><p class="error-text"></p><button class="btn">返信を保存（開発メールへ）</button></form></div>';return adminShell('inquiries',body);}
function classContactsAdmin(cl=1){cl=Math.max(1,Math.min(10,cl));const rows=state.classContacts.filter(c=>c.class===cl);let body='<div class="panel"><h2>クラス幹事を設定する</h2><p>各クラス最大3名。表示指定は管理権限と別です。管理者が変更します。</p><div class="class-tabs">'+Array.from({length:10},(_,i)=>'<a href="#/admin/contacts/'+(i+1)+'" class="'+(cl===i+1?'active':'')+'">3年'+(i+1)+'組</a>').join('')+'</div><h3>3年'+cl+'組</h3>'+table(['表示名','順番','操作'],rows.map(c=>[esc(state.people.find(p=>p.id===c.userId)?.name||'未登録'),c.position,'<form id="communityContactRemove-'+c.id+'" data-community="contactRemove" data-id="'+c.id+'">'+field('reason','解除理由')+'<button class="btn btn-outline">表示指定を解除</button></form>']))+'<h3>表示する幹事を追加</h3><form id="communityContactAdd" data-class="'+cl+'">'+select('userId','このクラスの参加予定者',state.people.filter(p=>p.class===cl&&R.active(p)).map(p=>[p.id,p.name]),'')+field('position','表示順（1〜3）',1,'number')+field('reason','指定理由')+'<p class="error-text"></p><button class="btn">クラス幹事として表示</button></form></div>';return adminShell('contacts',body);}
galleryPage=function(){const aid=Number(location.hash.split('/')[2]||0),albums=state.albums.filter(a=>a.visible).sort((a,b)=>a.position-b.position||a.id-b.id);return frame(title('PHOTO ALBUM','みんなの写真を、ここに。','幹事が名前を付けて公開したアルバムをお楽しみください。')+notice+'<p><a class="btn" href="#/my">写真を投稿する（申込確認へ） ↗</a></p>'+(organizer()?'<p><a class="btn btn-outline" href="#/admin/photos">アルバム名・写真を管理</a></p>':'')+'<div class="class-tabs"><a href="#/gallery" class="'+(!aid?'active':'')+'">すべてのアルバム</a>'+albums.map(a=>'<a href="#/gallery/'+a.id+'" class="'+(aid===a.id?'active':'')+'">'+esc(a.name)+'</a>').join('')+'</div>'+(state.settings.clock>state.settings.photoEnd?'<p class="panel">公開期限を過ぎています。</p>':albums.filter(a=>!aid||a.id===aid).map(a=>'<section class="section"><h2>'+esc(a.name)+'</h2><p>'+esc(a.description)+'</p><div class="gallery-grid">'+(albumCards(C.visiblePhotos(state,a.id))||'<p>写真は公開準備中です。</p>')+'</div></section>').join('')));};
photoPage=function(id){if(!C.visiblePhotos(state).some(p=>p.id===Number(id)))return frame(title('PHOTO ALBUM','公開中の写真がありません。'));return communityBasePhoto(id);};
function albumPicker(value=1){return select('albumId','アルバムの種類',state.albums.slice().sort((a,b)=>a.position-b.position).map(a=>[a.id,a.name+(a.visible?'':'（非表示）')]),value);}
function albumForm(a={}){return '<form id="communityAlbum-'+(a.id||0)+'" data-community="album" data-id="'+(a.id||0)+'">'+field('name','アルバム名',a.name||'')+field('description','説明',a.description||'','text',false)+field('position','表示順',a.position||1,'number')+select('visible','参加者への表示',[['yes','表示する'],['no','非表示']],a.visible===false?'no':'yes')+field('reason','設定理由')+'<p class="error-text"></p><button class="btn">'+(a.id?'設定を保存':'アルバムを追加')+'</button></form>';}
photosAdmin=function(){return adminShell('photos','<div class="panel"><h2>アルバムに、好きな名前を。</h2><p>名前やアルバム数は固定ではありません。自由に追加・改名して、写真をまとめられます。</p><h3>アルバムを追加</h3>'+albumForm()+'</div>'+state.albums.map(a=>'<details class="panel" open><summary>'+esc(a.name)+' ／ '+(a.visible?'表示':'非表示')+'</summary>'+albumForm(a)+'</details>').join('')+'<div class="panel"><h3>写真を登録</h3><p>公開可能な見本画像だけを、このブラウザー内へ保存します。</p><div id="uploadAlbumChoice">'+albumPicker()+'</div><label class="file-drop">JPEG/PNGを選択（1枚5MB以下・1回4枚）<input id="photoFiles" type="file" accept="image/jpeg,image/png" multiple></label></div><div class="panel"><h3>写真の公開とアルバム変更</h3>'+table(['見本','タイトル','種類・移動先','写真の公開'],state.photos.map(p=>['<img class="upload-preview" src="'+esc(p.src)+'" alt="'+esc(p.title)+'">',esc(p.title),'<form id="communityPhotoMove-'+p.id+'" data-community="photoMove" data-id="'+p.id+'">'+albumPicker(p.albumId)+field('reason','変更理由')+'<button class="btn btn-outline">アルバムを変更</button></form>',(p.published?'写真は公開':'写真は非公開')+'<br><button class="link" data-action="toggle-photo" data-id="'+p.id+'">'+(p.published?'写真を非公開に':'写真を公開する')+'</button>']))+'</div>');};
mailPage=function(){return adminShell('mail','<div class="panel"><h2>開発メール（実送信なし）</h2>'+state.mail.slice().reverse().map(m=>'<details><summary>'+esc(m.subject)+' ／ '+esc(m.to||state.people.find(p=>p.id===m.personId)?.email||'')+'</summary><p>宛先：'+esc(m.to||state.people.find(p=>p.id===m.personId)?.email||'未設定')+' ／ 開発用・未送信</p><pre class="message-body">'+esc(m.body)+'</pre></details>').join('')+'</div>');};
route=function(){C.prepare(state);if(pendingPhotoAlbum){const added=state.photos.filter(p=>!pendingPhotoAlbum.ids.has(p.id));if(added.length){const choice=pendingPhotoAlbum.album;pendingPhotoAlbum=null;change(s=>s.photos.filter(p=>added.some(a=>a.id===p.id)).forEach(p=>{p.albumId=choice;p.album=s.albums.find(a=>a.id===choice)?.name||'';}));}}const path=(location.hash.slice(1)||'/').split('/').filter(Boolean);if(path[0]==='contact'){main.innerHTML=frame(title('CONTACT US','幹事へのお問い合わせ。')+inquiryForm());window.scrollTo(0,0);return;}if(path[0]==='admin'&&['inquiries','contacts'].includes(path[1])){if(!current()||!organizer())return communityBaseRoute();if(path[1]==='contacts'&&!owner()){main.innerHTML=frame(title('ACCESS','管理者だけが設定できます。'));return;}main.innerHTML=path[1]==='inquiries'?inquiryAdmin(Number(path[2]||0)):classContactsAdmin(Number(path[2]||1));window.scrollTo(0,0);return;}communityBaseRoute();};
window.removeEventListener('hashchange',communityBaseRoute);window.addEventListener('hashchange',route);
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.id.startsWith('community'))return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));try{if(f.id==='communityInquiry'){const i=change(s=>C.inquiry(s,d,current()?.id||null));f.innerHTML='<div class="success-mark">✓</div><h2>見本の問い合わせを受け付けました。</h2><p>受付番号 Q87-'+String(i.id).padStart(5,'0')+'</p><p>このブラウザーの幹事画面で確認できます。実メールは送信していません。</p>';return;}if(!organizer())throw new Error('幹事のログインが必要です。');const id=Number(f.dataset.id);if(f.id==='communityReply')change(s=>C.reply(s,id,d.body,current().id));else if(f.id==='communityInquiryStatus')change(s=>C.status(s,id,d.status,Number(d.assignee),d.reason,current().id));else if(f.id==='communityContactAdd')change(s=>C.contactAdd(s,Number(f.dataset.class),Number(d.userId),Number(d.position),d.reason,current().id));else if(f.dataset.community==='contactRemove')change(s=>C.contactRemove(s,id,d.reason,current().id));else if(f.dataset.community==='album')change(s=>C.albumSave(s,{...d,id},current().id));else if(f.dataset.community==='photoMove')change(s=>C.photoMove(s,id,Number(d.albumId),d.reason,current().id));route();toast('内容と操作履歴を保存しました');}catch(e){const el=f.querySelector('.error-text');if(el)el.textContent=e.message;else toast(e.message);}},true);
document.addEventListener('change',ev=>{if(ev.target.id==='photoFiles')pendingPhotoAlbum={album:Number(document.querySelector('#uploadAlbumChoice [name=albumId]')?.value||1),ids:new Set(state.photos.map(p=>p.id))};},true);
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action="download-photo"]');if(b&&!C.visiblePhotos(state).some(p=>p.id===Number(b.dataset.id))){ev.stopImmediatePropagation();toast('公開中の写真ではありません。');}},true);
const contactNav=document.createElement('a');contactNav.href='#/contact';contactNav.textContent='お問い合わせ';document.querySelector('#mainNav').insertBefore(contactNav,document.querySelector('#mainNav .nav-cta'));
route();
